// SRAM (Static RAM): Cache Example (L1/L2)
struct CacheLine {
    uint64_t tag; // Address ID
    bool valid;
    uint8_t data[64]; // Block size (64B typical)
};

// DRAM (Dynamic RAM): Main Memory Abstraction
uint8_t MainMemory[1UL << 32]; // 4GB space

// Typical latency (ns) comparison
#define LATENCY_SRAM_L1 1
#define LATENCY_DRAM_MAIN 100

// Cache hit calculation principle
bool check_cache_hit(CacheLine lines[], uint64_t addr) {
    uint64_t desired_tag = addr >> 6;
    return (lines[addr % N_SETS].tag == desired_tag &&
            lines[addr % N_SETS].valid);
}
